"""The console server's SSH key: generated by Mercury, kept encrypted, only the public half shown.

docs/LAB9_PLAN.md section 8, "The security addition" and its recommendation: the console host
gives Mercury a DEDICATED key whose `authorized_keys` line forces the bridge wrapper
(modules/nsot/console_wrapper.py), so the key's whole power is "bridge to an allowlisted
console". Mercury generates the pair itself: the private half goes straight into Mercury's
credential store under a REFERENCE (encrypted at rest, `credentials.set_ssh_key`), and the
operator is shown only the public key and the exact line to install:

    restrict,command="<wrapper> <allowlist>" ssh-ed25519 AAAA... mercury-console

So the operator handles no secret, and none crosses the console. Nothing here returns, logs or
puts in an exception the private half; `load` hands it, parsed, to the one caller that signs
in with it (console_transport).
"""

import base64
import io
import logging
import re

from modules import credentials

log = logging.getLogger(__name__)

#: The key's comment: says on the console host whose key it is.
COMMENT = "mercury-console"
KEY_TYPE = "ssh-ed25519"
#: The `authorized_keys` options: `restrict` turns off forwarding, a pty, agent and X11, and
#: `command=` forces the wrapper whatever the client asks to run.
OPTIONS = "restrict"
#: A path inside `command="..."`: absolute, and no space, quote, backslash or line break (the
#: wrapper and its allowlist are two words of one quoted command).
PATH = re.compile(r"/[A-Za-z0-9._/-]{0,255}")


#: Generate's steps, in order (`generate`; the manual names each, `modules/manual.OPERATIONS`).
STEPS = (("check", "The reference, the user and both paths checked before a key is made"),
         ("generate", "A new ed25519 pair, made here"),
         ("store", "The private half encrypted in the credential store under the reference"),
         ("show", "Only the public key, its fingerprint and the exact authorized_keys line"))
#: Where a console host's host step installs the bridge wrapper and its allowlist
#: (modules/nsot/console_wrapper.py's own example line): the defaults the key's form offers.
WRAPPER_PATH = "/usr/local/lib/nmas/nmas-console-bridge"
ALLOWLIST_PATH = "/etc/nmas/console-allowlist"


class ConsoleKeyUnavailable(RuntimeError):
    """No usable key under a reference; the text names the reference, never a value."""


def check_path(what: str, path) -> str:
    """*path* when it may stand in the forced command; else ValueError naming it."""
    if not isinstance(path, str) or not PATH.fullmatch(path) or "/../" in path + "/":
        raise ValueError(f"the {what} path {path!r} is not an absolute path of letters, digits, "
                         f"'.', '_', '-' and '/' (it must match {PATH.pattern}, with no '..' "
                         "step)")
    return path


def authorized_keys_line(public_key: str, wrapper_path: str, allowlist_path: str) -> str:
    """The exact line the operator installs on the console host for *public_key*."""
    check_path("wrapper", wrapper_path)
    check_path("allowlist", allowlist_path)
    fields = public_key.split() if isinstance(public_key, str) else []
    if len(fields) != 3 or fields[0] != KEY_TYPE or fields[2] != COMMENT:
        raise ValueError(f"{public_key!r} is not one {KEY_TYPE} public key with the comment "
                         f"{COMMENT!r}")
    return f'{OPTIONS},command="{wrapper_path} {allowlist_path}" {public_key}'


def fingerprint(public_key: str) -> str:
    """The public key's SHA256 fingerprint, as `ssh-keygen -l` prints it."""
    from modules.host_keys import fingerprint_of
    return fingerprint_of(base64.b64decode(public_key.split()[1]))


def generate(ref: str, *, username: str, wrapper_path: str, allowlist_path: str,
             replace: bool = False) -> dict:
    """A new ed25519 key pair for a console server: the private half stored under *ref* in
    the credential store, encrypted; returned are ONLY ``{"ok", "ref", "username",
    "public_key", "fingerprint", "authorized_keys_line"}``. Every argument is checked before
    a key is made; a key already under *ref* is refused unless *replace*
    (`credentials.SshKeyExists`)."""
    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

    credentials.check_ssh_key_ref(ref)
    check_path("wrapper", wrapper_path)
    check_path("allowlist", allowlist_path)
    key = Ed25519PrivateKey.generate()
    public = key.public_key().public_bytes(serialization.Encoding.OpenSSH,
                                           serialization.PublicFormat.OpenSSH).decode()
    public = f"{public} {COMMENT}"
    credentials.set_ssh_key(
        ref, username=username, replace=replace, public_key=public,
        private_key=key.private_bytes(serialization.Encoding.PEM,
                                      serialization.PrivateFormat.OpenSSH,
                                      serialization.NoEncryption()).decode())
    line = authorized_keys_line(public, wrapper_path, allowlist_path)
    log.info("console key: generated %s for %s as %s (%s)", ref, username, KEY_TYPE,
             fingerprint(public))
    return {"ok": True, "ref": ref, "username": username, "public_key": public,
            "fingerprint": fingerprint(public), "authorized_keys_line": line}


def load(ref: str) -> tuple:
    """``(username, paramiko key)`` for the key stored under *ref*, for signing in; else
    ConsoleKeyUnavailable naming *ref* and why (absent, undecryptable, or not a key)."""
    import paramiko

    stored = credentials.get_ssh_key(ref)
    if stored is None:
        raise ConsoleKeyUnavailable(f"no SSH key is stored under {ref!r}")
    if not stored["private_key"]:
        raise ConsoleKeyUnavailable(f"the SSH key under {ref!r} could not be decrypted (the "
                                    "credential store's key file may have changed)")
    try:
        pkey = paramiko.Ed25519Key(file_obj=io.StringIO(stored["private_key"]))
    except Exception:                         # noqa: BLE001 - its words could quote the key
        raise ConsoleKeyUnavailable(f"the SSH key under {ref!r} is not an {KEY_TYPE} private "
                                    "key paramiko can read") from None
    return stored["username"], pkey
